import { useIntl } from 'react-intl';

import type { ChartData } from 'chart.js';
import { Skeleton } from 'components';
import { Doughnut } from 'components/Chart';
import { StyledChipLabel } from 'components/ChartHeader/ChartHeader.styles';

import type { PortfolioPieChartData, PortfolioPieSlice } from '../../types';
import {
  PORTFOLIO_PIE_CHART_COLORS_BY_ID,
  PORTFOLIO_PIE_CHART_HEIGHT,
  PORTFOLIO_PIE_CHART_OPTIONS,
} from './config/portfolioPieChartConfig';
import {
  StyledPortfolioPieChartEmpty,
  StyledPortfolioPieChartHeading,
  StyledPortfolioPieChartInner,
  StyledPortfolioPieChartPeriodChip,
  StyledPortfolioPieChartPeriodChipWrap,
  StyledPortfolioPieChartPlot,
  StyledPortfolioPieChartRoot,
  StyledPortfolioPieChartTitle,
  StyledPortfolioPieChartTitleRow,
  StyledPortfolioPieChartTitleSkeleton,
  StyledPortfolioPieLegend,
  StyledPortfolioPieLegendItem,
  StyledPortfolioPieLegendSwatch,
} from './PortfolioPieChart.styles';

export interface PortfolioPieChartProps {
  chartId: PortfolioPieChartData['id'];
  title: string;
  period?: string;
  slices: PortfolioPieSlice[];
  loading?: boolean;
  dataTestId?: string;
}

const LegendItem = ({ color, label }: { color: string; label: string }) => (
  <StyledPortfolioPieLegendItem>
    <StyledPortfolioPieLegendSwatch style={{ backgroundColor: color }} />
    {label}
  </StyledPortfolioPieLegendItem>
);

const renderChartTitle = (
  title: string,
  period?: string,
  dataTestId?: string,
) => (
  <StyledPortfolioPieChartTitleRow>
    <StyledPortfolioPieChartHeading>{title}</StyledPortfolioPieChartHeading>
    {period ? (
      <StyledPortfolioPieChartPeriodChipWrap
        data-testid={dataTestId ? `${dataTestId}-period` : undefined}
      >
        <StyledPortfolioPieChartPeriodChip disabled $noMargin>
          <StyledChipLabel>{period}</StyledChipLabel>
        </StyledPortfolioPieChartPeriodChip>
      </StyledPortfolioPieChartPeriodChipWrap>
    ) : null}
  </StyledPortfolioPieChartTitleRow>
);

const PortfolioPieChartSkeleton = ({ dataTestId }: { dataTestId?: string }) => (
  <StyledPortfolioPieChartRoot data-testid={dataTestId}>
    <StyledPortfolioPieChartTitle>
      <StyledPortfolioPieChartTitleSkeleton>
        <Skeleton
          height="20px"
          width="60%"
          length={1}
          borderRadius="small"
          hasContainer={false}
          dataTestId={dataTestId ? `${dataTestId}-title-skeleton` : undefined}
        />
      </StyledPortfolioPieChartTitleSkeleton>
    </StyledPortfolioPieChartTitle>
    <StyledPortfolioPieChartInner>
      <Skeleton
        height="16px"
        width="70%"
        length={1}
        borderRadius="small"
        hasContainer={false}
        dataTestId={dataTestId ? `${dataTestId}-legend-skeleton` : undefined}
      />
      <StyledPortfolioPieChartPlot skeleton>
        <Skeleton
          height="100%"
          width="100%"
          length={1}
          borderRadius="medium"
          hasContainer={false}
          dataTestId={dataTestId ? `${dataTestId}-plot-skeleton` : undefined}
        />
      </StyledPortfolioPieChartPlot>
    </StyledPortfolioPieChartInner>
  </StyledPortfolioPieChartRoot>
);

export const PortfolioPieChart: React.FC<PortfolioPieChartProps> = ({
  chartId,
  title,
  period,
  slices,
  loading,
  dataTestId,
}) => {
  const { formatMessage } = useIntl();

  if (loading) {
    return <PortfolioPieChartSkeleton dataTestId={dataTestId} />;
  }

  if (!slices.length) {
    return (
      <StyledPortfolioPieChartRoot data-testid={dataTestId}>
        <StyledPortfolioPieChartTitle>
          {renderChartTitle(title, period, dataTestId)}
        </StyledPortfolioPieChartTitle>
        <StyledPortfolioPieChartInner>
          <StyledPortfolioPieChartEmpty
            data-testid={
              dataTestId ? `${dataTestId}-empty` : 'portfolio-pie-chart-empty'
            }
          >
            {formatMessage({
              id: 'Innovation.InnovationHub.Overview.Portfolio.emptyState',
            })}
          </StyledPortfolioPieChartEmpty>
        </StyledPortfolioPieChartInner>
      </StyledPortfolioPieChartRoot>
    );
  }

  const chartColors = PORTFOLIO_PIE_CHART_COLORS_BY_ID[chartId];
  const sliceColor = (index: number) => chartColors[index % chartColors.length];

  const chartData: ChartData<'doughnut'> = {
    labels: slices.map((s) => s.label),
    datasets: [
      {
        data: slices.map((s) => s.percentage),
        backgroundColor: slices.map((_, i) => sliceColor(i)),
        borderColor: slices.map((s) => s.borderColor ?? '#ffffff'),
        borderWidth: slices.map((s) => s.borderWidth ?? 0.5),
      },
    ],
  };

  return (
    <StyledPortfolioPieChartRoot data-testid={dataTestId}>
      <StyledPortfolioPieChartTitle>
        {renderChartTitle(title, period, dataTestId)}
      </StyledPortfolioPieChartTitle>
      <StyledPortfolioPieChartInner>
        <StyledPortfolioPieLegend>
          {slices.map((s, i) => (
            <LegendItem
              key={`${s.label}-${i}`}
              color={sliceColor(i)}
              label={s.label}
            />
          ))}
        </StyledPortfolioPieLegend>
        <StyledPortfolioPieChartPlot>
          <Doughnut
            data={chartData}
            options={PORTFOLIO_PIE_CHART_OPTIONS}
            height={PORTFOLIO_PIE_CHART_HEIGHT}
            dataTestId={dataTestId ? `${dataTestId}-doughnut` : undefined}
          />
        </StyledPortfolioPieChartPlot>
      </StyledPortfolioPieChartInner>
    </StyledPortfolioPieChartRoot>
  );
};
